package com.aoo.bcg.common.cache;
import java.util.Locale;
/** Canonical cache key: env:domain:entity:id:vN. */
public record CacheKey(String environment,String domain,String entity,String id,int schemaVersion){public CacheKey{environment=part(environment,"environment");domain=part(domain,"domain");entity=part(entity,"entity");id=identifier(id);if(schemaVersion<=0)throw new IllegalArgumentException("schemaVersion must be positive");}public static CacheKey of(String environment,String domain,String entity,long id,int schemaVersion){if(id<=0)throw new IllegalArgumentException("id must be positive");return new CacheKey(environment,domain,entity,Long.toString(id),schemaVersion);}public String value(){return String.join(":",environment,domain,entity,id,"v"+schemaVersion);}public String shardedValue(int shard){if(shard<0||shard>999)throw new IllegalArgumentException("invalid shard");return String.join(":",environment,domain,entity,String.format(java.util.Locale.ROOT,"{%s-%03d}",domain,shard),id,"v"+schemaVersion);}private static String part(String value,String name){if(value==null||!value.matches("[a-z][a-z0-9_-]{1,31}"))throw new IllegalArgumentException("invalid "+name);return value.toLowerCase(Locale.ROOT);}private static String identifier(String value){if(value==null||!value.matches("[A-Za-z0-9_-]{1,128}"))throw new IllegalArgumentException("invalid id");return value;}}
